const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Point([121.47, 31.23]).buffer(50000); // 50km radius around Shanghai

  const period1Start = '2020-02-10';
  const period1End = '2020-02-26';
  const period2Start = '2020-04-20';
  const period2End = '2020-05-13';

  // 2. Data Acquisition & Check
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  const col1 = no2Collection
    .filterDate(period1Start, period1End)
    .filterBounds(shanghai);

  const col2 = no2Collection
    .filterDate(period2Start, period2End)
    .filterBounds(shanghai);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Period 1 (Feb 10-25): ${size1} images`);
  console.log(`Period 2 (Apr 20-May 12): ${size2} images`);

  if (size1 === 0 || size2 === 0) {
    console.log('Empty collection for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing with quality filtering
  function maskQuality(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.75);
    return image.updateMask(mask);
  }

  const col1Masked = col1.map(maskQuality);
  const col2Masked = col2.map(maskQuality);

  const mean1 = col1Masked.mean();
  const mean2 = col2Masked.mean();

  // 4. Calculation
  const stats1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: shanghai,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: shanghai,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const val1 = stats1.tropospheric_NO2_column_number_density_mean;
  const count1 = stats1.tropospheric_NO2_column_number_density_count;
  const val2 = stats2.tropospheric_NO2_column_number_density_mean;
  const count2 = stats2.tropospheric_NO2_column_number_density_count;

  console.log(`Period 1: Mean NO2 = ${val1}, Valid pixels = ${count1}`);
  console.log(`Period 2: Mean NO2 = ${val2}, Valid pixels = ${count2}`);

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after quality masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (val1 === null || val1 === undefined || val2 === null || val2 === undefined ||
      isNaN(val1) || isNaN(val2)) {
    console.log('Calculation failed: invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Change: ${((val2 - val1) / val1 * 100).toFixed(2)}%`);

  if (val2 > val1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
